using System.Diagnostics;
using System.Text;
using NexaStation.Core;
using NexaStation.Domain;

namespace NexaStation.Infrastructure.RemotePlay;

public static class RemotePlayArgumentTemplate
{
    private static readonly string[] Allowed=["{TARGET_LABEL}","{HOST_HINT}","{DISPLAY_WIDTH}","{DISPLAY_HEIGHT}"];
    public static IReadOnlyList<string> Render(string? template,RemotePlayProfile profile,int width=0,int height=0)
    {
        if(string.IsNullOrWhiteSpace(template))return [];if(template.IndexOfAny(['&','|',';','>','<','\r','\n','`'])>=0||template.Contains("$(",StringComparison.Ordinal)||template.Contains('%'))throw new InvalidOperationException("Remote-play arguments cannot contain shell operators or expansion syntax.");string value=template;foreach(string token in ExtractTokens(value))if(!Allowed.Contains(token,StringComparer.Ordinal))throw new InvalidOperationException($"Remote-play argument variable {token} is not allowed.");value=value.Replace("{TARGET_LABEL}",profile.TargetLabel??string.Empty,StringComparison.Ordinal).Replace("{HOST_HINT}",profile.HostHint??string.Empty,StringComparison.Ordinal).Replace("{DISPLAY_WIDTH}",width.ToString(System.Globalization.CultureInfo.InvariantCulture),StringComparison.Ordinal).Replace("{DISPLAY_HEIGHT}",height.ToString(System.Globalization.CultureInfo.InvariantCulture),StringComparison.Ordinal);return Parse(value);
    }
    private static IEnumerable<string> ExtractTokens(string value){int index=0;while((index=value.IndexOf('{',index))>=0){int end=value.IndexOf('}',index+1);if(end<0)throw new InvalidOperationException("Remote-play argument template contains an incomplete variable.");yield return value[index..(end+1)];index=end+1;}}
    private static List<string> Parse(string value){List<string> args=[];StringBuilder current=new();bool quoted=false;for(int i=0;i<value.Length;i++){char c=value[i];if(c=='\"'){quoted=!quoted;continue;}if(char.IsWhiteSpace(c)&&!quoted){if(current.Length>0){args.Add(current.ToString());current.Clear();}continue;}current.Append(c);}if(quoted)throw new InvalidOperationException("Remote-play arguments contain an unmatched quote.");if(current.Length>0)args.Add(current.ToString());return args;}
}

public sealed class RemotePlayLaunchService(IRemotePlayProfileStore profiles,ILibraryRepository library,IProcessLauncher processes,IFrontendWindowService window,IActivityTimelineService timeline,IActivityPrivacyService privacy) : IRemotePlayLaunchService
{
    public async Task<RemotePlayValidationResult> ValidateAsync(string profileId,CancellationToken cancellationToken=default)
    {RemotePlayProfile? profile=await profiles.GetAsync(profileId,cancellationToken).ConfigureAwait(false);if(profile is null||!profile.Enabled)return new(false,"The remote-play profile is unavailable.",[]);LibraryItem? item=await library.GetByIdAsync(profile.ApplicationLibraryItemId,cancellationToken).ConfigureAwait(false);if(item is null)return new(false,"The configured remote-play application is missing.",[]);LaunchTarget? target=profile.LaunchTargetId is null?item.LaunchTarget:item.LaunchTargets.FirstOrDefault(v=>v.Id==profile.LaunchTargetId);if(target is null||!target.IsEnabled)return new(false,"The configured launch target is unavailable.",[]);try{return new(true,"The profile is ready.",RemotePlayArgumentTemplate.Render(profile.ArgumentsTemplate,profile));}catch(InvalidOperationException ex){return new(false,ex.Message,[]);}}
    public async Task<RemotePlayLaunchResult> LaunchAsync(string profileId,CancellationToken cancellationToken=default)
    {
        RemotePlayValidationResult valid=await ValidateAsync(profileId,cancellationToken).ConfigureAwait(false);if(!valid.Valid)return new(false,null,valid.Message);RemotePlayProfile profile=(await profiles.GetAsync(profileId,cancellationToken).ConfigureAwait(false))!;LibraryItem item=(await library.GetByIdAsync(profile.ApplicationLibraryItemId,cancellationToken).ConfigureAwait(false))!;LaunchTarget target=(profile.LaunchTargetId is null?item.LaunchTarget:item.LaunchTargets.First(v=>v.Id==profile.LaunchTargetId))!;target=target with{ArgumentList=valid.RenderedArguments,Arguments=null,HideFrontendWhileRunning=profile.HideFrontend,RestoreFrontendAfterExit=profile.RestoreFrontend,TrackingMode=profile.TrackingMode};string sessionId=Guid.NewGuid().ToString("N");DateTime started=DateTime.UtcNow;ActivityPrivacyLevel level=await privacy.EvaluateAsync(item,cancellationToken).ConfigureAwait(false);await timeline.RecordAsync(new(Guid.NewGuid().ToString("N"),ActivityEventType.RemotePlayStarted,ActivityTargetType.RemotePlayProfile,profile.Id,sessionId,profile.Name,profile.TargetLabel,target.ProviderId,null,started,null,null,ActivityResult.Succeeded,level,CreatedAtUtc:started),cancellationToken).ConfigureAwait(false);
        Stopwatch elapsed=Stopwatch.StartNew();try{RunningProcess process=await processes.StartAsync(target,cancellationToken).ConfigureAwait(false);await using(process.ConfigureAwait(false)){if(profile.HideFrontend)await window.HideAsync().ConfigureAwait(false);if(profile.TrackingMode is not (ApplicationTrackingMode.None or ApplicationTrackingMode.ManualReturn))await process.WaitForExitAsync().ConfigureAwait(false);}elapsed.Stop();if(profile.RestoreFrontend){await window.BringToForegroundAsync().ConfigureAwait(false);await window.RestoreFullscreenAsync().ConfigureAwait(false);}DateTime ended=DateTime.UtcNow;await timeline.RecordAsync(new(Guid.NewGuid().ToString("N"),ActivityEventType.RemotePlayEnded,ActivityTargetType.RemotePlayProfile,profile.Id,sessionId,profile.Name,profile.TargetLabel,target.ProviderId,null,ended,ended,(long)elapsed.Elapsed.TotalSeconds,ActivityResult.Succeeded,level,CreatedAtUtc:ended),CancellationToken.None).ConfigureAwait(false);return new(true,sessionId,"Remote-play session completed.");}catch(Exception ex){if(profile.RestoreFrontend){await window.BringToForegroundAsync().ConfigureAwait(false);await window.RestoreFullscreenAsync().ConfigureAwait(false);}DateTime ended=DateTime.UtcNow;await timeline.RecordAsync(new(Guid.NewGuid().ToString("N"),ActivityEventType.RemotePlayEnded,ActivityTargetType.RemotePlayProfile,profile.Id,sessionId,profile.Name,profile.TargetLabel,target.ProviderId,null,ended,ended,(long)elapsed.Elapsed.TotalSeconds,ActivityResult.Failed,level,MetadataJson:System.Text.Json.JsonSerializer.Serialize(new{Failure=ex.GetType().Name}),CreatedAtUtc:ended),CancellationToken.None).ConfigureAwait(false);return new(false,sessionId,"The remote-play application could not be started.");}
    }
}
